const { useState, useEffect } = React;

const COURSES = [
  { id: 1, name: '리액트 입문', hours: 8 },
  { id: 2, name: 'CSS 레이아웃', hours: 6 },
  { id: 3, name: '자바스크립트 기초', hours: 12 },
];

const MENU = [
  { href: '#/', label: '홈' },
  { href: '#/courses', label: '코스' },
];

function readRoute() {
  return window.location.hash.slice(1) || '/';
}

function NavLink({ href, label, route }) {
  const here = href.slice(1) === route;

  return (
    <a href={href} aria-current={here ? 'page' : undefined}>
      {label}
    </a>
  );
}

function Detail({ id }) {
  const course = COURSES.find((c) => c.id === id);

  if (!course) {
    return (
      <div>
        <p className="state">그런 코스가 없습니다</p>
        <p className="course"><a href="#/courses">목록으로</a></p>
      </div>
    );
  }

  return (
    <div>
      <p className="state">{course.name}</p>
      <p className="course">{course.hours}시간</p>
    </div>
  );
}

function App() {
  const [route, setRoute] = useState(readRoute());

  useEffect(() => {
    const onChange = () => setRoute(readRoute());
    window.addEventListener('hashchange', onChange);
    return () => window.removeEventListener('hashchange', onChange);
  }, []);

  const parts = route.split('/').filter((piece) => piece !== '');

  return (
    <div>
      <nav className="nav">
        {MENU.map((item) => (
          <NavLink key={item.href} href={item.href} label={item.label} route={route} />
        ))}
      </nav>
      {parts[0] !== 'courses' ? (
        <p className="state">홈 화면입니다</p>
      ) : parts.length === 1 ? (
        <div>
          <p className="state">코스 {COURSES.length}개</p>
          {COURSES.map((c) => (
            <p className="course" key={c.id}>
              <a href={'#/courses/' + c.id}>{c.name}</a>
            </p>
          ))}
        </div>
      ) : (
        <Detail id={Number(parts[1])} />
      )}
    </div>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

